// task-2157: the published paper strategies (GUARDRAILS §12): the frozen S2 / S3 / T2 rules, their gates-off twins and the
// stream challenge pair ship as presets. Generated by the authors' make-presets script (rules identical to what was
// backtested / run on paper, text rewritten for the public); these tests pin what a public preset may and may not say.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { isDeepStrictEqual } from 'node:util';
import { presetPath, validateStrategy } from '../src/strategy.ts';
import { StrategyStore } from '../src/store.ts';

const BASE = ['ss-s2-old-holders', 'ss-s3-old-scalp', 'ss-t2-trend-hold60'];
const OPEN = BASE.map((id) => `${id}-open`);
const STREAM = ['stream-c30-fresh', 'stream-c30-trend'];
const ALL = [...BASE, ...OPEN, ...STREAM];
const raw = (id: string) => JSON.parse(readFileSync(presetPath(id), 'utf8'));

/** Every string VALUE of a document (keys like the schema's `rugproof` are the app's names and are not scanned). */
function strings(v: unknown, out: string[] = []): string[] {
  if (typeof v === 'string') out.push(v);
  else if (Array.isArray(v)) for (const x of v) strings(x, out);
  else if (v && typeof v === 'object') for (const x of Object.values(v)) strings(x, out);
  return out;
}

test('2157 published presets: all eight validate, are paper and mechanical, and list as presets', () => {
  const ids = new StrategyStore({ env: { DEXTERM_HOME: '/nonexistent-2157' } }).presetIds();
  for (const id of ALL) {
    assert.ok(ids.includes(id), `${id} is a preset`);
    const d = raw(id);
    assert.equal(d.id, id);
    const r = validateStrategy(d);
    assert.ok(r.ok, `${id}: ${!r.ok ? JSON.stringify(r.errors) : ''}`);
    assert.equal(d.mode, 'paper');
    assert.equal(d.entry.decide, 'auto', `${id}: no model session per coin`);
    assert.match(d.description, /^PAPER only, simulated fills, not financial advice\./, `${id}: the label leads`);
  }
});

test('2157 published presets: no private text, no §3 words, no coin or wallet addresses', () => {
  const banned: [RegExp, string][] = [
    [/\/(Users|home)\/|~\/|[A-Za-z]:\\/, 'a local path'],
    [/\btask-\d+/i, 'an internal task id'],
    [/\b(research|launch|scripts)\/|\.(md|py|mjs|sh)\b/, 'a repo path'],
    [/@|\.local\b|\.ts\.net\b|\bwsl\b|\bhttps?:\/\//i, 'an email, a host name or a URL'],
    [/rug-?proof/i, 'the §3 word rug-proof'],
    [/finds? winners|\balpha\b|guarantee|predict/i, 'a §3 claim'],
    [/[1-9A-HJ-NP-Za-km-z]{32,44}/, 'a base58 address'],
  ];
  for (const id of ALL) for (const s of strings(raw(id))) for (const [re, what] of banned) assert.doesNotMatch(s, re, `${id}: ${what} in ${JSON.stringify(s)}`);
});

test('2157 gates-off twins differ from their base only in the holder-safety / pool-safety gates and the text', () => {
  for (const id of BASE) {
    const b = raw(id), o = raw(`${id}-open`);
    assert.match(o.description, /OPEN version: the same entry and exit rules with the holder-safety and pool-safety gates switched OFF/);
    for (const k of ['sizing', 'risk', 'agent', 'execution', 'bankroll', 'mode', 'version']) assert.deepEqual(o[k], b[k], `${id}-open ${k}`);
    assert.deepEqual(o.exits, b.exits, `${id}-open exits`);
    assert.deepEqual(o.entry.ageHours, b.entry.ageHours);
    assert.deepEqual(o.entry.triggers, b.entry.triggers);
    const s = o.entry.safety;
    assert.equal(s.maxTop10Pct, null); assert.equal(s.maxDevPct, null);
    assert.equal(s.requireNoMintAuthority, false); assert.equal(s.requireNoFreezeAuthority, false);
    assert.equal(s.youngVertical, null);
    assert.ok(s.rugproof === null || s.rugproof.requireSafePool === false, `${id}-open: the pool chain is off`);
    assert.doesNotMatch(o.entry.screen, /!flag:(mint|freeze)/);
    assert.ok(!isDeepStrictEqual(o.entry.safety, b.entry.safety));
  }
  // T2's own 2 h pool-age floor is its entry rule, not a copied gate: it stays in the twin
  assert.equal(raw('ss-t2-trend-hold60-open').entry.safety.rugproof.minPoolAgeMin, 120);
});

test('2157 T2 ships as the modified variant and says so', () => {
  for (const id of ['ss-t2-trend-hold60', 'ss-t2-trend-hold60-open']) {
    const d = raw(id);
    assert.match(d.name, /modified/i);
    assert.match(d.description, /top-trending/);
    assert.match(d.description, /(cannot express that filter|not in this file)/);
  }
});
